        let at_threshold = "a".repeat(PREVIOUS_FEEDBACK_ELISION_THRESHOLD);
        assert!(!bound_previous_feedback(at_threshold).contains("bytes elided"));

        let over_threshold = "a".repeat(PREVIOUS_FEEDBACK_ELISION_THRESHOLD + 1);
