    /// Process group children must die with the parent: spawn a check node
    /// that forks a grandchild via `sh -c` subshell, then verify the
    /// grandchild is gone after the check is terminated.
    #[cfg(unix)]
    #[tokio::test]
    async fn process_group_children_die_with_parent() {
        let (dir, db, engine, graph_id, spec_id) = graph_fixture().unwrap();
        let marker = dir.path().join("grandchild_alive");

        // The check node forks a grandchild that sleeps and touches a
        // marker file. If the process group kill works, the grandchild
        // dies before the marker appears.
        db.insert_graph_node(&GraphNode {
            id: "check-pg".to_string(),
            spec_id: Some(spec_id.clone()),
            graph_id: None,
            name: "check-pg".to_string(),
            kind: GraphNodeKind::Check,
            config: serde_json::json!({
                "command": format!(
                    "( sleep 60; touch \"{}\" ) & exit 1",
                    marker.display()
                ),
                "success_condition": "exit_code_0",
                "timeout_seconds": 3,
            }),
            position: 1,
            created_at: chrono::Utc::now(),
        })
        .unwrap();

        engine
            .run_graph(graph_id.clone(), None, None, None, None, None)
            .await
            .unwrap();

        // Wait for the grace period + a bit extra for the grandchild.
        tokio::time::sleep(std::time::Duration::from_secs(4)).await;

        assert!(
            !marker.exists(),
            "grandchild process should have been killed by process-group termination; \
             marker file should not exist"
        );
    }

    // ── F1: ensemble execution (execute_ensemble) ───────────────────────

    /// Writes an executable POSIX shell script at `dir/name` with `body` as
    /// its content and returns its absolute path. Used to give each
    /// ensemble member deterministic, script-controlled pass/fail/hang
    /// behavior — the member's actual prompt content is irrelevant (the
    /// script ignores stdin/argv entirely), so this sidesteps having to
    /// reverse-engineer `render_agent_prompt`'s wrapped output as a runnable
    /// shell script.
    fn write_member_script(dir: &std::path::Path, name: &str, body: &str) -> String {
        let path = dir.join(name);
        std::fs::write(&path, format!("#!/bin/sh\n{body}\n")).unwrap();
        #[cfg(unix)]
        {
            use std::os::unix::fs::PermissionsExt;
            std::fs::set_permissions(&path, std::fs::Permissions::from_mode(0o755)).unwrap();
        }
        path.to_string_lossy().to_string()
    }

    /// CB57: a shell fragment that re-executes the test binary itself
    /// (`self_report_exe`, filtered to `graph_engine::tests::
    /// self_report_verdict_writer`) so a fake member script files its own
    /// self-report verdict as the last thing it does before exiting — see
    /// that test's doc comment for why the process-exit ordering can never
    /// race the engine. Values are passed to the child as `CANOPY_TEST_*`
    /// command-prefix env assignments (the child is the writer; in-suite
    /// the variable is never set, so the no-op early-return holds under
    /// any harness). `status` is `"pass"` or `"fail"`. The stdout string
    /// is only passed when `Some`: with `None` the writer files no
    /// `stdout` key, exactly like the old positional-4 invocation. None of
    /// this file's fixed stdout strings ("A", "B", "OK",
    /// "NODE_OUTPUT_DATA_1", ...) contain a single quote, so naive
    /// single-quoting is safe here; this is not a general-purpose shell
    /// escaper. The child's stdout (libtest chatter) goes to /dev/null so
    /// the member's own stdout stays byte-identical; panics print to
    /// stderr and the 101 exit still fails the member script loudly.
    fn self_report_invocation(
        db_path: &std::path::Path,
        node_id: &str,
        status: &str,
        stdout: Option<&str>,
    ) -> String {
        let exe = self_report_exe();
        let mut vars = format!(
            "CANOPY_TEST_SELF_REPORT_DB='{}' CANOPY_TEST_SELF_REPORT_NODE_ID='{node_id}' CANOPY_TEST_SELF_REPORT_STATUS='{status}'",
            db_path.display()
        );
        if let Some(text) = stdout {
            vars += &format!(" CANOPY_TEST_SELF_REPORT_STDOUT='{text}'");
        }
        format!(
            "{vars} '{exe}' --exact graph_engine::tests::self_report_verdict_writer --nocapture >/dev/null\n"
        )
    }

    /// CB57: like [`write_member_script`], but appends a
    /// [`self_report_invocation`] after `body` so the script files its own
    /// verdict before exiting — replacing the old background-poller pattern
    /// for members whose script never calls back into the engine.
    fn write_self_reporting_member_script(
        dir: &std::path::Path,
        name: &str,
        body: &str,
        db_path: &std::path::Path,
        node_id: &str,
        status: &str,
        stdout: Option<&str>,
    ) -> String {
        let full_body = format!(
            "{body}\n{}",
            self_report_invocation(db_path, node_id, status, stdout)
        );
        write_member_script(dir, name, &full_body)
    }

    /// CB57 (FR5): the re-executed verdict writer. A fake member script
    /// re-runs the test binary itself (`self_report_exe`, filtered with
    /// `--exact graph_engine::tests::self_report_verdict_writer
    /// --nocapture` — see `self_report_invocation`) and this test files
    /// that member's own self-report straight into the run's database
    /// using the real `get_active_graph_run_for_node` +
    /// `update_graph_run_result` — the same calls `graph_complete_node`
    /// makes; no SQL is hand-mirrored. Node id, status and stdout come
    /// from `CANOPY_TEST_SELF_REPORT_NODE_ID`, `_STATUS` and `_STDOUT`
    /// (when `_STDOUT` is set — even to the empty string — its value is
    /// filed as the row's `stdout`, matching the old binary's shape). With
    /// `CANOPY_TEST_SELF_REPORT_DB` unset — every ordinary suite run —
    /// this test returns immediately.
    ///
    /// The ordering guarantee it inherits from the deleted binary: the
    /// engine always inserts the run row with status `running` before it
    /// spawns the member process, and never reads that row back until the
    /// process has exited — so a write done here, inside the grandchild
    /// the member's script waits on, is ordered before the engine's read
    /// by process-exit semantics, not by winning a race against a timer.
    /// Panics if no running row exists: that would mean the ordering
    /// above broke — a real defect to see in test output, not something
    /// to retry past.
    #[test]
    fn self_report_verdict_writer() {
        let Some(db_path) = std::env::var_os("CANOPY_TEST_SELF_REPORT_DB") else {
            return;
        };
        let node_id = std::env::var("CANOPY_TEST_SELF_REPORT_NODE_ID")
            .expect("a script that sets CANOPY_TEST_SELF_REPORT_DB also sets the node id");
        let status = match std::env::var("CANOPY_TEST_SELF_REPORT_STATUS")
            .expect("a script that sets CANOPY_TEST_SELF_REPORT_DB also sets the status")
            .as_str()
        {
            "pass" => GraphRunStatus::Pass,
            "fail" => GraphRunStatus::Fail,
            other => panic!("self_report_verdict_writer: bad status {other:?}"),
        };
        let stdout_text = std::env::var("CANOPY_TEST_SELF_REPORT_STDOUT").ok();

        let file_verdict = || -> Result<()> {
            let db = Database::new(&std::path::PathBuf::from(&db_path))?;
            let run = db
                .get_active_graph_run_for_node(&node_id)?
                .ok_or_else(|| anyhow!("no running graph_run row for node {node_id:?}"))?;
            let mut output = serde_json::json!({ "test_self_report": true });
            if let Some(text) = &stdout_text {
                output["stdout"] = Value::String(text.clone());
            }
            let updated = db.update_graph_run_result(
                run.id.as_str(),
                status,
                Some(&output),
                Some(chrono::Utc::now()),
            )?;
            if !updated {
                bail!(
                    "graph_run row {} vanished between lookup and update",
                    run.id
                );
            }
            Ok(())
        };

        // Deviation D1: the deleted binary opened its own connection with
        // a 5 s SQLite busy timeout; `Database::new` sets none, and its
        // open-time seeding performs short write transactions that can
        // collide with the engine's writes under a loaded suite. Retry
        // ONLY on "database is locked" (SQLITE_BUSY), waiting — this is
        // the busy handler, not a verdict retry: the filing still happens
        // before the member process exits (what orders it against the
        // engine's read), a missing running row fails on the first
        // attempt, and any other error panics immediately. Budget ~5 s.
        for attempt in 0..50u32 {
            match file_verdict() {
                Ok(()) => return,
                Err(e) if attempt < 49 && e.to_string().contains("database is locked") => {
                    std::thread::sleep(std::time::Duration::from_millis(100));
                }
                Err(e) => panic!("self_report_verdict_writer: {e}"),
            }
        }
    }

    /// A fake `.canopy/config.toml` registering one CLI entry per
    /// `(name, binary)` pair — lets each ensemble member run its own script
    /// under its own `platform` name, so a single ensemble can exercise
    /// pass/fail/hang members side by side in the same run.
    fn setup_multi_cli_home(clis: &[(&str, &str)]) -> tempfile::TempDir {
        let fake_home = tempfile::tempdir().unwrap();
        let canopy_dir = fake_home.path().join(".canopy");
        std::fs::create_dir_all(&canopy_dir).unwrap();
        let config = crate::domain::canopy_config::CanopyConfig {
            configured_at: Some(chrono::Utc::now().to_rfc3339()),
            clis: clis
                .iter()
                .map(|(name, binary)| crate::domain::cli_config::CliConfig {
                    name: name.to_string(),
                    binary: binary.to_string(),
                    headless_mode: String::new(),
                    model_flag: None,
                    supports_working_dir: false,
                    working_dir_flag: None,
                    env_vars: std::collections::HashMap::new(),
                    interactive_args: None,
                    fallback_interactive_args: None,
                    resume_args: None,
                    session_list_cmd: None,
                    session_resume_cmd: None,
                    accent_color: None,
                    yolo_flag: None,
                    prompt_via_stdin: true,
                    ..Default::default()
                })
                .collect(),
            ..Default::default()
        };
        config.save_for_tests(&canopy_dir).unwrap();
        fake_home
    }

    /// CM30: one fake-home CLI entry with a platform-level infra-retry
    /// budget: `(name, binary, infra_retry_limit, infra_crash_max_seconds,
    /// infra_backoff_seconds)`.
    type InfraCliEntry<'a> = (&'a str, &'a str, Option<u32>, Option<u64>, Option<u64>);

    /// CM30: like [`setup_multi_cli_home`] but each entry also carries the
    /// platform-level infra-retry budget
    /// `(name, binary, infra_retry_limit, infra_crash_max_seconds,
    /// infra_backoff_seconds)` — `None` per field means "platform sets
    /// nothing, the engine default applies". A separate helper (rather than
    /// an extended signature) so the 20+ existing `setup_multi_cli_home`
    /// callers keep working positionally.
    fn setup_multi_cli_home_with_infra(clis: &[InfraCliEntry<'_>]) -> tempfile::TempDir {
        let fake_home = tempfile::tempdir().unwrap();
        let canopy_dir = fake_home.path().join(".canopy");
        std::fs::create_dir_all(&canopy_dir).unwrap();
        let config = crate::domain::canopy_config::CanopyConfig {
            configured_at: Some(chrono::Utc::now().to_rfc3339()),
            clis: clis
                .iter()
                .map(|(name, binary, retry_limit, crash_max, backoff)| {
                    crate::domain::cli_config::CliConfig {
                        name: name.to_string(),
                        binary: binary.to_string(),
                        headless_mode: String::new(),
                        model_flag: None,
                        supports_working_dir: false,
                        working_dir_flag: None,
                        env_vars: std::collections::HashMap::new(),
                        interactive_args: None,
                        fallback_interactive_args: None,
                        resume_args: None,
                        session_list_cmd: None,
                        session_resume_cmd: None,
                        accent_color: None,
                        yolo_flag: None,
                        prompt_via_stdin: true,
                        infra_retry_limit: *retry_limit,
                        infra_crash_max_seconds: *crash_max,
                        infra_backoff_seconds: *backoff,
                        ..Default::default()
                    }
                })
                .collect(),
            ..Default::default()
        };
        config.save_for_tests(&canopy_dir).unwrap();
        fake_home
    }

    /// Like [`setup_multi_cli_home`] but for CM26 resume tests: the caller
    /// builds each member's full [`crate::domain::cli_config::CliConfig`]
    /// (session_resume_cmd / session_id_set_flag / per-member env such as its
    /// own `ARGV_FILE`) via [`argv_cli_config`] rather than the bare
    /// name/binary pair `setup_multi_cli_home` accepts.
    fn setup_multi_resume_cli_home(
        clis: Vec<crate::domain::cli_config::CliConfig>,
    ) -> tempfile::TempDir {
        let fake_home = tempfile::tempdir().unwrap();
        let canopy_dir = fake_home.path().join(".canopy");
        std::fs::create_dir_all(&canopy_dir).unwrap();
        let config = crate::domain::canopy_config::CanopyConfig {
            configured_at: Some(chrono::Utc::now().to_rfc3339()),
            clis,
            ..Default::default()
        };
        config.save_for_tests(&canopy_dir).unwrap();
        fake_home
    }

    /// Builds a real ensemble unit (kickoff -> N members -> join -> pass/fail
    /// exits) directly against the DB, the same shape `graph_add_ensemble`
    /// assembles in one MCP call — but constructed here node-by-node so
    /// engine tests can drive it through the real `execute_ensemble` path
    /// via `GraphEngine::run_graph` without spinning up the MCP server.
    #[expect(clippy::too_many_arguments)]
    fn insert_test_ensemble(
        db: &Database,
        spec_id: &str,
        kickoff_id: &str,
        ensemble_id: &str,
        join_id: &str,
        members: &[(&str, &str)], // (node_id, cli_platform_name)
        min_pass: i64,
        straggler_timeout_minutes: Option<i64>,
        quorum_grace_minutes: Option<i64>,
        on_pass_to: &str,
        on_fail_to: Option<&str>,
    ) {
        let now = chrono::Utc::now();

        db.insert_graph_node(&GraphNode {
            id: kickoff_id.to_string(),
            spec_id: Some(spec_id.to_string()),
            graph_id: None,
            name: "kickoff".to_string(),
            kind: GraphNodeKind::Check,
            config: serde_json::json!({
                "command": "printf ok",
                "success_condition": "exit_code_0"
            }),
            position: 1,
            created_at: now,
        })
        .unwrap();

        let member_nodes: Vec<GraphNode> = members
            .iter()
            .enumerate()
            .map(|(i, (node_id, platform))| GraphNode {
                id: node_id.to_string(),
                spec_id: Some(spec_id.to_string()),
                graph_id: None,
                name: format!("member-{}", i + 1),
                kind: GraphNodeKind::Agent,
                config: serde_json::json!({
                    "platform": platform,
                    "prompt_template": "ignored by the member's test script",
                    "timeout_minutes": 5,
                    // A member that exits non-zero inside `crash_max_seconds`
                    // reads as an infra crash, so the engine retries it behind
                    // the doubling backoff. At the 30s default that parked two
                    // of these tests on a real 60s sleep each and set the floor
                    // for the whole suite; zero keeps the retry path exercised
                    // without the wait.
                    "infra_backoff_seconds": 0,
                }),
                position: 2 + i as i64,
                created_at: now,
            })
            .collect();

        let join_node = GraphNode {
            id: join_id.to_string(),
            spec_id: Some(spec_id.to_string()),
            graph_id: None,
            name: "quorum".to_string(),
            kind: GraphNodeKind::Join,
            config: serde_json::json!({ "ensemble_id": ensemble_id }),
            position: 2 + members.len() as i64,
            created_at: now,
        };

        let mut edges = Vec::new();
        for (node_id, _) in members {
            edges.push(GraphEdge {
                id: format!("{kickoff_id}->{node_id}"),
                spec_id: Some(spec_id.to_string()),
                graph_id: None,
                from_node: kickoff_id.to_string(),
                to_node: node_id.to_string(),
                condition: GraphEdgeCondition::Always,
            });
            edges.push(GraphEdge {
                id: format!("{node_id}->{join_id}"),
                spec_id: Some(spec_id.to_string()),
                graph_id: None,
                from_node: node_id.to_string(),
                to_node: join_id.to_string(),
                condition: GraphEdgeCondition::Always,
            });
        }
        edges.push(GraphEdge {
            id: format!("{join_id}->pass"),
            spec_id: Some(spec_id.to_string()),
            graph_id: None,
            from_node: join_id.to_string(),
            to_node: on_pass_to.to_string(),
            condition: GraphEdgeCondition::Pass,
        });
        if let Some(fail_to) = on_fail_to {
            edges.push(GraphEdge {
                id: format!("{join_id}->fail"),
                spec_id: Some(spec_id.to_string()),
                graph_id: None,
                from_node: join_id.to_string(),
                to_node: fail_to.to_string(),
                condition: GraphEdgeCondition::Fail,
            });
        }

        let ensemble = crate::domain::graphs::Ensemble {
            commit_rights: false,
            id: ensemble_id.to_string(),
            spec_id: Some(spec_id.to_string()),
            graph_id: None,
            name: "Test Ensemble".to_string(),
            prompt_template: "ignored by the member's test script".to_string(),
            join_node_id: join_id.to_string(),
            entry_from_node: kickoff_id.to_string(),
            entry_condition: GraphEdgeCondition::Always,
            min_pass,
            straggler_timeout_minutes,
            quorum_grace_minutes,
            timeout_minutes: 5,
            infra_retry_limit: None,
            infra_crash_max_seconds: None,
            infra_backoff_seconds: None,
            on_pass_to: on_pass_to.to_string(),
            on_fail_to: on_fail_to.map(str::to_string),
            kind: crate::domain::graphs::EnsembleKind::Parallel,
            round_robin_index: None,
            created_at: now,

            crew_id: None,
            crew_name: None,
            crew_version_applied: None,
        };
        let ensemble_members: Vec<EnsembleMember> = members
            .iter()
            .enumerate()
            .map(|(i, (node_id, platform))| EnsembleMember {
                ensemble_id: ensemble_id.to_string(),
                node_id: node_id.to_string(),
                position: i as i64,
                platform: platform.to_string(),
                model: None,
                prompt_override: None,
                timeout_minutes: None,
                infra_retry_limit: None,
                infra_crash_max_seconds: None,
                infra_backoff_seconds: None,
            })
            .collect();

        db.insert_ensemble_unit(
            &ensemble,
            &ensemble_members,
            &member_nodes,
            &join_node,
            &edges,
        )
        .unwrap();
    }

    /// CM26: like [`insert_test_ensemble`] but the ensemble `kind` and
    /// round-robin's starting index are caller-chosen, since the CM26 tests
    /// need a bounce edge to route back INTO the ensemble (one `GraphEdge`
    /// per member, `to_node` = that member's node id, matching condition —
    /// the `select_next_step` fan-out convention documented on
    /// [`select_next_step`]) rather than always terminating at a fixed
    /// pass/fail node the way [`insert_test_ensemble`] does.
    #[expect(clippy::too_many_arguments)]
    fn insert_bouncing_ensemble(
        db: &Database,
        spec_id: &str,
        kind: crate::domain::graphs::EnsembleKind,
        members: &[(&str, &str)], // (node_id, cli_platform_name)
        min_pass: i64,
        straggler_timeout_minutes: Option<i64>,
        round_robin_index: Option<i64>,
        on_pass_to: &str,
        on_fail_to: &str,
    ) {
        let now = chrono::Utc::now();

        db.insert_graph_node(&GraphNode {
            id: "kickoff".to_string(),
            spec_id: Some(spec_id.to_string()),
            graph_id: None,
            name: "kickoff".to_string(),
            kind: GraphNodeKind::Check,
            config: serde_json::json!({ "command": "printf ok", "success_condition": "exit_code_0" }),
            position: 1,
            created_at: now,
        })
        .unwrap();

        let member_nodes: Vec<GraphNode> = members
            .iter()
            .enumerate()
            .map(|(i, (node_id, platform))| GraphNode {
                id: node_id.to_string(),
                spec_id: Some(spec_id.to_string()),
                graph_id: None,
                name: format!("member-{}", i + 1),
                kind: GraphNodeKind::Agent,
                config: serde_json::json!({
                    "platform": platform,
                    "prompt_template": "ignored by the member's test script",
                    "timeout_minutes": 5,
                    "infra_backoff_seconds": 0,
                }),
                position: 2 + i as i64,
                created_at: now,
            })
            .collect();

        let join_node = GraphNode {
            id: "join1".to_string(),
            spec_id: Some(spec_id.to_string()),
            graph_id: None,
            name: "join".to_string(),
            kind: GraphNodeKind::Join,
            config: serde_json::json!({ "ensemble_id": "ens1" }),
            position: 50,
            created_at: now,
        };

        let mut edges = Vec::new();
        for (node_id, _) in members {
            edges.push(GraphEdge {
                id: format!("kickoff->{node_id}"),
                spec_id: Some(spec_id.to_string()),
                graph_id: None,
                from_node: "kickoff".to_string(),
                to_node: node_id.to_string(),
                condition: GraphEdgeCondition::Always,
            });
            edges.push(GraphEdge {
                id: format!("{node_id}->join1"),
                spec_id: Some(spec_id.to_string()),
                graph_id: None,
                from_node: node_id.to_string(),
                to_node: "join1".to_string(),
                condition: GraphEdgeCondition::Always,
            });
        }
        edges.push(GraphEdge {
            id: "join1->pass".to_string(),
            spec_id: Some(spec_id.to_string()),
            graph_id: None,
            from_node: "join1".to_string(),
            to_node: on_pass_to.to_string(),
            condition: GraphEdgeCondition::Pass,
        });
        edges.push(GraphEdge {
            id: "join1->fail".to_string(),
            spec_id: Some(spec_id.to_string()),
            graph_id: None,
            from_node: "join1".to_string(),
            to_node: on_fail_to.to_string(),
            condition: GraphEdgeCondition::Fail,
        });

        let ensemble = crate::domain::graphs::Ensemble {
            commit_rights: false,
            id: "ens1".to_string(),
            spec_id: Some(spec_id.to_string()),
            graph_id: None,
            name: "Bouncing Ensemble".to_string(),
            prompt_template: "ignored by the member's test script".to_string(),
            join_node_id: "join1".to_string(),
            entry_from_node: "kickoff".to_string(),
            entry_condition: GraphEdgeCondition::Always,
            min_pass,
            straggler_timeout_minutes,
            quorum_grace_minutes: None,
            timeout_minutes: 5,
            infra_retry_limit: None,
            infra_crash_max_seconds: None,
            infra_backoff_seconds: None,
            on_pass_to: on_pass_to.to_string(),
            on_fail_to: Some(on_fail_to.to_string()),
            kind,
            round_robin_index,
            created_at: now,

            crew_id: None,
            crew_name: None,
            crew_version_applied: None,
        };
        let ensemble_members: Vec<EnsembleMember> = members
            .iter()
            .enumerate()
            .map(|(i, (node_id, platform))| EnsembleMember {
                ensemble_id: "ens1".to_string(),
                node_id: node_id.to_string(),
                position: i as i64,
                platform: platform.to_string(),
                model: None,
                prompt_override: None,
                timeout_minutes: None,
                infra_retry_limit: None,
                infra_crash_max_seconds: None,
                infra_backoff_seconds: None,
            })
            .collect();

        db.insert_ensemble_unit(
            &ensemble,
            &ensemble_members,
            &member_nodes,
            &join_node,
            &edges,
        )
        .unwrap();
    }

    /// Edges routing a gate node's `Fail` verdict back INTO the ensemble
    /// (`ens1`) — one `GraphEdge` per member, `to_node` = that member's node
    /// id, condition `Fail`, matching `select_next_step`'s "distinct targets
    /// equal one ensemble's member set" fan-out convention.
    fn bounce_edges_into_ensemble(
        spec_id: &str,
        gate_id: &str,
        member_ids: &[&str],
    ) -> Vec<GraphEdge> {
        member_ids
            .iter()
            .map(|member_id| GraphEdge {
                id: format!("{gate_id}->{member_id}"),
                spec_id: Some(spec_id.to_string()),
                graph_id: None,
                from_node: gate_id.to_string(),
                to_node: member_id.to_string(),
                condition: GraphEdgeCondition::Fail,
            })
            .collect()
    }

    /// A `Check` node that fails on its first invocation and passes
    /// (`printf APPROVED`) from the second invocation on — used to force
    /// exactly one bounce back into an ensemble before a spec is allowed to
    /// terminate.
    fn counter_gate_node(
        id: &str,
        spec_id: &str,
        counter: &std::path::Path,
        position: i64,
    ) -> GraphNode {
        GraphNode {
            id: id.to_string(),
            spec_id: Some(spec_id.to_string()),
            graph_id: None,
            name: id.to_string(),
            kind: GraphNodeKind::Check,
            config: serde_json::json!({
                "command": format!(
                    "n=$(cat \"{c}\" 2>/dev/null || echo 0); n=$((n+1)); echo $n > \"{c}\"; [ \"$n\" -ge 2 ] && printf APPROVED || exit 1",
                    c = counter.display(),
                ),
                "success_condition": "exit_code_0"
            }),
            position,
            created_at: chrono::Utc::now(),
        }
    }

    /// CM26 FR1: a parallel bounce resumes the member whose last run in this
    /// spec passed, and cold-starts a member whose last run was a straggler
    /// kill. `member-pass` (self-reports Pass as the last thing its script
    /// does before exiting) and `member-straggler`
    /// (never filed; its own node-level `timeout_minutes: 0` — NOT the
    /// ensemble's shared `straggler_timeout_minutes`, which the parallel path
    /// applies to every member alike and would kill `member-pass` too —
    /// forces its own agent timeout to fire immediately every dispatch) run
    /// twice each. A counter-gate downstream of the join bounces back into
    /// the ensemble exactly once before letting the spec finish.
    #[tokio::test]
    async fn parallel_bounce_resumes_passer_and_cold_starts_straggler() {
        let (dir, db, engine, graph_id, spec_id) = graph_fixture().unwrap();
        let db_path = dir.path().join(TEST_DB_FILENAME);
        let script = write_argv_echo_cli(dir.path());

        let argv_pass = dir.path().join("argv-pass.log");
        let mut env_pass = HashMap::new();
        env_pass.insert(
            "ARGV_FILE".to_string(),
            argv_pass.to_string_lossy().into_owned(),
        );
        env_pass.insert("RESUME_FLAG".to_string(), "--resume".to_string());
        env_pass.insert("LINGER_SECONDS".to_string(), "1".to_string());
        env_pass.insert("SELF_REPORT_NODE_ID".to_string(), "member-pass".to_string());
        env_pass.insert("SELF_REPORT_EXE".to_string(), self_report_exe());
        env_pass.insert(
            "SELF_REPORT_DB".to_string(),
            db_path.to_string_lossy().into_owned(),
        );
        let mut cli_pass =
            argv_cli_config(&script, env_pass, Some("--resume"), Some("--set"), None);
        cli_pass.name = "cli-pass".to_string();

        let argv_straggler = dir.path().join("argv-straggler.log");
        let mut env_straggler = HashMap::new();
        env_straggler.insert(
            "ARGV_FILE".to_string(),
            argv_straggler.to_string_lossy().into_owned(),
        );
        env_straggler.insert("RESUME_FLAG".to_string(), "--resume".to_string());
        env_straggler.insert("LINGER_SECONDS".to_string(), "3".to_string());
        let mut cli_straggler = argv_cli_config(
            &script,
            env_straggler,
            Some("--resume"),
            Some("--set"),
            None,
        );
        cli_straggler.name = "cli-straggler".to_string();

        let home = setup_multi_resume_cli_home(vec![cli_pass, cli_straggler]);

        let counter = dir.path().join("gate-counter");
        db.insert_graph_node(&counter_gate_node("gate", &spec_id, &counter, 60))
            .unwrap();
        let done_marker = dir.path().join("done.marker");
        db.insert_graph_node(&touch_marker_node("done", &spec_id, &done_marker, 61))
            .unwrap();

        insert_bouncing_ensemble(
            &db,
            &spec_id,
            EnsembleKind::Parallel,
            &[
                ("member-pass", "cli-pass"),
                ("member-straggler", "cli-straggler"),
            ],
            1,
            Some(5),
            None,
            "gate",
            "done",
        );
        // Force member-straggler's OWN agent timeout to fire immediately,
        // every dispatch, without touching the ensemble's shared straggler
        // window (which `member-pass` shares and needs to survive).
        db.update_graph_node_details(
            "member-straggler",
            None,
            None,
            Some(&serde_json::json!({
                "platform": "cli-straggler",
                "prompt_template": "ignored by the member's test script",
                "timeout_minutes": 0,
                "infra_backoff_seconds": 0,
            })),
            None,
        )
        .unwrap();
        db.insert_graph_edge(&GraphEdge {
            id: "gate->done".to_string(),
            spec_id: Some(spec_id.clone()),
            graph_id: None,
            from_node: "gate".to_string(),
            to_node: "done".to_string(),
            condition: GraphEdgeCondition::Pass,
        })
        .unwrap();
        for edge in
            bounce_edges_into_ensemble(&spec_id, "gate", &["member-pass", "member-straggler"])
        {
            db.insert_graph_edge(&edge).unwrap();
        }

        let _home = HomeGuard::set(home.path());
        engine
            .run_graph(graph_id, None, None, None, None, None)
            .await
            .unwrap();
        drop(_home);

        assert!(
            done_marker.exists(),
            "gate must eventually pass (second visit) and reach the terminal node"
        );

        let pass_runs = member_runs(&db, &spec_id, "member-pass");
        assert_eq!(
            pass_runs.len(),
            2,
            "member-pass must run once per ensemble dispatch"
        );
        let first_session = pass_runs[0]
            .session_id
            .clone()
            .expect("first (cold) run must capture a session id via --set");
        assert_eq!(
            pass_runs[1].session_id.as_deref(),
            Some(first_session.as_str()),
            "the resumed run's row keeps the SAME session id, never a fresh one"
        );

        let argv_pass_text = std::fs::read_to_string(&argv_pass).unwrap();
        let chunks: Vec<&str> = argv_pass_text.split("===\n").collect();
        assert!(
            !chunks[0].contains("--resume"),
            "member-pass's first visit must be cold"
        );
        assert!(
            chunks[1].contains("--resume") && chunks[1].contains(&first_session),
            "member-pass's second visit must resume the SAME session id the spawn actually received"
        );

        let straggler_runs = member_runs(&db, &spec_id, "member-straggler");
        assert_eq!(
            straggler_runs.len(),
            2,
            "member-straggler must run once per ensemble dispatch"
        );
        for run in &straggler_runs {
            assert_eq!(
                run.status,
                GraphRunStatus::Fail,
                "the straggler is killed by the 0-minute timeout every dispatch"
            );
        }
        let argv_straggler_text = std::fs::read_to_string(&argv_straggler).unwrap_or_default();
        assert!(
            !argv_straggler_text.contains("--resume"),
            "a member that never passed must never be offered a resume candidate"
        );
    }

    /// CM26 FR2: round-robin's full within-spec contract in one topology —
    /// `rr-a` (position 0) always fails, `rr-b` (position 1) always passes.
    /// Visit 1 (cold, index 0) fails -> bounce. Visit 2 (bounce, pinned=0,
    /// absent from `resumable_sessions` since it just failed -> advance to 1,
    /// cold) passes -> bounce. Visit 3 (bounce, pinned=1, present -> resume)
    /// passes -> spec ends. `rr-a` must never be revisited once the pin
    /// advances past it, and the persisted `round_robin_index` must land on
    /// 1 and stay there through the resumed visit 3 (which writes nothing).
    #[tokio::test]
    async fn round_robin_bounce_after_fail_advances_then_resumes_and_stays() {
        let (dir, db, engine, graph_id, spec_id) = graph_fixture().unwrap();
        let db_path = dir.path().join(TEST_DB_FILENAME);
        let script = write_argv_echo_cli(dir.path());

        let argv_a = dir.path().join("argv-a.log");
        let mut env_a = HashMap::new();
        env_a.insert(
            "ARGV_FILE".to_string(),
            argv_a.to_string_lossy().into_owned(),
        );
        env_a.insert("RESUME_FLAG".to_string(), "--resume".to_string());
        env_a.insert("LINGER_SECONDS".to_string(), "1".to_string());
        env_a.insert("SELF_REPORT_NODE_ID".to_string(), "rr-a".to_string());
        env_a.insert("SELF_REPORT_EXE".to_string(), self_report_exe());
        env_a.insert(
            "SELF_REPORT_DB".to_string(),
            db_path.to_string_lossy().into_owned(),
        );
        env_a.insert("SELF_REPORT_STATUS".to_string(), "fail".to_string());
        let mut cli_a = argv_cli_config(&script, env_a, Some("--resume"), Some("--set"), None);
        cli_a.name = "cli-a".to_string();

        let argv_b = dir.path().join("argv-b.log");
        let mut env_b = HashMap::new();
        env_b.insert(
            "ARGV_FILE".to_string(),
            argv_b.to_string_lossy().into_owned(),
        );
        env_b.insert("RESUME_FLAG".to_string(), "--resume".to_string());
        env_b.insert("LINGER_SECONDS".to_string(), "1".to_string());
        env_b.insert("SELF_REPORT_NODE_ID".to_string(), "rr-b".to_string());
        env_b.insert("SELF_REPORT_EXE".to_string(), self_report_exe());
        env_b.insert(
            "SELF_REPORT_DB".to_string(),
            db_path.to_string_lossy().into_owned(),
        );
        let mut cli_b = argv_cli_config(&script, env_b, Some("--resume"), Some("--set"), None);
        cli_b.name = "cli-b".to_string();

        let home = setup_multi_resume_cli_home(vec![cli_a, cli_b]);

        let counter_fail = dir.path().join("gate-fail-counter");
        db.insert_graph_node(&counter_gate_node(
            "retry-gate-fail",
            &spec_id,
            &counter_fail,
            60,
        ))
        .unwrap();
        let counter_pass = dir.path().join("gate-pass-counter");
        db.insert_graph_node(&counter_gate_node(
            "retry-gate-pass",
            &spec_id,
            &counter_pass,
            61,
        ))
        .unwrap();
        let done_via_fail_gate = dir.path().join("done-via-fail-gate.marker");
        db.insert_graph_node(&touch_marker_node(
            "done-via-fail-gate",
            &spec_id,
            &done_via_fail_gate,
            62,
        ))
        .unwrap();
        let done_via_pass_gate = dir.path().join("done-via-pass-gate.marker");
        db.insert_graph_node(&touch_marker_node(
            "done-via-pass-gate",
            &spec_id,
            &done_via_pass_gate,
            63,
        ))
        .unwrap();

        insert_bouncing_ensemble(
            &db,
            &spec_id,
            EnsembleKind::RoundRobin,
            &[("rr-a", "cli-a"), ("rr-b", "cli-b")],
            1,
            Some(1),
            Some(0),
            "retry-gate-pass",
            "retry-gate-fail",
        );
        db.insert_graph_edge(&GraphEdge {
            id: "fail-gate->done".to_string(),
            spec_id: Some(spec_id.clone()),
            graph_id: None,
            from_node: "retry-gate-fail".to_string(),
            to_node: "done-via-fail-gate".to_string(),
            condition: GraphEdgeCondition::Pass,
        })
        .unwrap();
        db.insert_graph_edge(&GraphEdge {
            id: "pass-gate->done".to_string(),
            spec_id: Some(spec_id.clone()),
            graph_id: None,
            from_node: "retry-gate-pass".to_string(),
            to_node: "done-via-pass-gate".to_string(),
            condition: GraphEdgeCondition::Pass,
        })
        .unwrap();
        for edge in bounce_edges_into_ensemble(&spec_id, "retry-gate-fail", &["rr-a", "rr-b"]) {
            db.insert_graph_edge(&edge).unwrap();
        }
        for edge in bounce_edges_into_ensemble(&spec_id, "retry-gate-pass", &["rr-a", "rr-b"]) {
            db.insert_graph_edge(&edge).unwrap();
        }

        let _home = HomeGuard::set(home.path());
        engine
            .run_graph(graph_id, None, None, None, None, None)
            .await
            .unwrap();
        drop(_home);

        assert!(
            done_via_pass_gate.exists(),
            "the spec must finish via the pass-gate's second (APPROVED) call"
        );
        assert!(
            !done_via_fail_gate.exists(),
            "the fail-gate must never see its own second call in this sequence"
        );

        let a_runs = member_runs(&db, &spec_id, "rr-a");
        assert_eq!(
            a_runs.len(),
            1,
            "rr-a must never be revisited once the pin advances past it"
        );
        assert_eq!(a_runs[0].status, GraphRunStatus::Fail);

        let b_runs = member_runs(&db, &spec_id, "rr-b");
        assert_eq!(b_runs.len(), 2, "rr-b runs the cold advance and the resume");
        assert_eq!(b_runs[0].status, GraphRunStatus::Pass);
        assert_eq!(b_runs[1].status, GraphRunStatus::Pass);
        let b_session = b_runs[0]
            .session_id
            .clone()
            .expect("rr-b's cold run must capture a session id via --set");
        assert_eq!(
            b_runs[1].session_id.as_deref(),
            Some(b_session.as_str()),
            "rr-b's resumed run keeps the SAME session id"
        );

        let argv_b_text = std::fs::read_to_string(&argv_b).unwrap();
        let chunks: Vec<&str> = argv_b_text.split("===\n").collect();
        assert!(
            !chunks[0].contains("--resume"),
            "rr-b's cold advance visit must not resume"
        );
        assert!(
            chunks[1].contains("--resume") && chunks[1].contains(&b_session),
            "rr-b's third-visit run must resume the SAME session id"
        );

        assert_eq!(
            db.get_ensemble("ens1").unwrap().unwrap().round_robin_index,
            Some(1),
            "the persisted index lands on rr-b (set once, during the fail-advance) \
             and is unchanged by the later resume, which writes nothing"
        );
    }

    /// CM26 FR3: a cascade bounce resumes at the member that produced the
    /// previous pass, not position 0. `casc-a` (position 0) is a genuinely
    /// crashing script with no self-report, so visit 1 exhausts its infra
    /// retries and falls through to `casc-b` (position 1), which passes cold.
    /// The gate bounces once; visit 2 must start directly at `casc-b`,
    /// resumed — `casc-a` must not run again.
    #[tokio::test]
    async fn cascade_bounce_resumes_previous_passer() {
        let (dir, db, engine, graph_id, spec_id) = graph_fixture().unwrap();
        let db_path = dir.path().join(TEST_DB_FILENAME);

        let crash_script = write_member_script(dir.path(), "crash.sh", "exit 1");
        let cli_crash = crate::domain::cli_config::CliConfig {
            name: "cli-crash".to_string(),
            binary: crash_script,
            headless_mode: String::new(),
            prompt_via_stdin: true,
            ..Default::default()
        };

        let script_b = write_argv_echo_cli(dir.path());
        let argv_b = dir.path().join("argv-b.log");
        let mut env_b = HashMap::new();
        env_b.insert(
            "ARGV_FILE".to_string(),
            argv_b.to_string_lossy().into_owned(),
        );
        env_b.insert("RESUME_FLAG".to_string(), "--resume".to_string());
        env_b.insert("LINGER_SECONDS".to_string(), "1".to_string());
        env_b.insert("SELF_REPORT_NODE_ID".to_string(), "casc-b".to_string());
        env_b.insert("SELF_REPORT_EXE".to_string(), self_report_exe());
        env_b.insert(
            "SELF_REPORT_DB".to_string(),
            db_path.to_string_lossy().into_owned(),
        );
        let mut cli_b = argv_cli_config(&script_b, env_b, Some("--resume"), Some("--set"), None);
        cli_b.name = "cli-b".to_string();

        let home = setup_multi_resume_cli_home(vec![cli_crash, cli_b]);

        let counter = dir.path().join("gate-counter");
        db.insert_graph_node(&counter_gate_node("gate", &spec_id, &counter, 60))
            .unwrap();
        let done_marker = dir.path().join("done.marker");
        db.insert_graph_node(&touch_marker_node("done", &spec_id, &done_marker, 61))
            .unwrap();

        insert_bouncing_ensemble(
            &db,
            &spec_id,
            EnsembleKind::Cascade,
            &[("casc-a", "cli-crash"), ("casc-b", "cli-b")],
            1,
            Some(1),
            None,
            "gate",
            "done",
        );
        db.insert_graph_edge(&GraphEdge {
            id: "gate->done".to_string(),
            spec_id: Some(spec_id.clone()),
            graph_id: None,
            from_node: "gate".to_string(),
            to_node: "done".to_string(),
            condition: GraphEdgeCondition::Pass,
        })
        .unwrap();
        for edge in bounce_edges_into_ensemble(&spec_id, "gate", &["casc-a", "casc-b"]) {
            db.insert_graph_edge(&edge).unwrap();
        }

        let _home = HomeGuard::set(home.path());
        engine
            .run_graph(graph_id, None, None, None, None, None)
            .await
            .unwrap();
        drop(_home);

        assert!(
            done_marker.exists(),
            "the gate's second call must pass and reach the terminal node"
        );

        let a_runs_after = member_runs(&db, &spec_id, "casc-a").len();
        assert_eq!(
            a_runs_after, 3,
            "casc-a exhausts its infra-retry budget once in visit 1 (initial + 2 retries) \
             and must NOT run again in visit 2 — proves the walk started at casc-b, not position 0"
        );

        let b_runs = member_runs(&db, &spec_id, "casc-b");
        assert_eq!(
            b_runs.len(),
            2,
            "casc-b runs once cold (visit 1's fallthrough) and once resumed (visit 2)"
        );
        assert_eq!(b_runs[0].status, GraphRunStatus::Pass);
        assert_eq!(b_runs[1].status, GraphRunStatus::Pass);
        let first_session = b_runs[0]
            .session_id
            .clone()
            .expect("casc-b's cold run must capture a session id via --set");
        assert_eq!(
            b_runs[1].session_id.as_deref(),
            Some(first_session.as_str()),
            "casc-b's resumed run keeps the SAME session id"
        );

        let argv_b_text = std::fs::read_to_string(&argv_b).unwrap();
        let chunks: Vec<&str> = argv_b_text.split("===\n").collect();
        assert!(
            !chunks[0].contains("--resume"),
            "casc-b's first (fallthrough) visit must be cold"
        );
        assert!(
            chunks[1].contains("--resume") && chunks[1].contains(&first_session),
            "casc-b's second visit must resume the SAME session id"
        );
    }

